import sys
from collections import defaultdict

def compute_min_length(A):
    if all(a == 0 for a in A):
        return 0
    if len(A) == 1:
        return 0

    # Group cities by their significance
    groups = defaultdict(list)
    for idx, a in enumerate(A):
        groups[a].append(idx)

    # Check if all cities have the same significance
    if len(groups) == 1:
        a = A[0]
        return a * (len(A) - 1)

    # Find all possible bit lengths that can be used as road lengths
