    # The key observation is that L must be a common bitmask of some pair (a, b)
    # So for each bit position, if it's set in at least two A_i's, it can be part of L
    # So we can consider all possible L that are bitwise AND of some pair in groups
    # But enumerating all pairs is O(N^2), which is too slow for N=1e5
    # Instead, we can consider all possible L that are bitwise AND of some subset of bits present in at least two A_i's

    # Collect all bits that appear in at least two A_i's
    bit_positions = set()
    for a in groups.keys():
        if a == 0:
            continue
        bits = set()
        temp = a
        pos = 0
        while temp > 0:
            if temp & 1:
                bits.add(pos)
            temp >>= 1
            pos += 1
        for bit in bits:
            bit_positions.add(bit)

    if not bit_positions:
        return -1

    max_bit = max(bit_positions) if bit_positions else 0
    max_L = 1 << (max_bit + 1) if max_bit >= 0 else 1

    # Now, we need to find the minimal spanning tree where each edge has length L
    # and (a & b & L) = L for the two cities connected by the edge
    # This is equivalent to saying that L must be a subset of the bits that are common in a and b
    # So for each possible L, we can build a graph where edges exist between cities if (a & b & L) = L
    # Then, we need to find the minimal spanning tree in this graph, and the total length is (number of edges) * L
    # We need to find the L that minimizes this total length

    # The minimal spanning tree will have (N-1) edges, so the total length is (N-1)*L
    # So we need to find the minimal L such that the graph is connected under the condition (a & b & L) = L

    # The condition (a & b & L) = L is equivalent to L being a subset of (a & b)
    # So for each possible L, we can check if the graph is connected where edges exist if L is a subset of (a & b)

    # The possible L's are all possible bitmasks formed by the bits in bit_positions
    # We can iterate over all possible L's in increasing order, and for each L, check if the graph is connected
    # The first L for which the graph is connected gives the minimal total length (N-1)*L

    # Generate all possible L's in increasing order
    possible_Ls = []
    for mask in range(0, 1 << (max_bit + 1)):
        L = mask
        if L == 0:
            continue
        # Check if L is a subset of at least one pair (a & b)
        valid = False
        for a in groups.keys():
            if a == 0:
