        if valid:
            possible_Ls.append(L)

    possible_Ls.sort()

    # Now, for each L in possible_Ls, check if the graph is connected
    for L in possible_Ls:
        # Build adjacency list
        adj = defaultdict(list)
        for a in groups.keys():
            if a == 0:
